/// Compiler version stamped into `manifest.json` and `runtime/index.ts`.
pub const COMPILER_VERSION: &str = "0.0.0";
/// Runtime version stamped into `manifest.json` and `runtime/index.ts`.
pub const RUNTIME_VERSION: &str = "0.0.0";

/// The banner every generated TypeScript module starts with, as its first line.
pub const GENERATED_BANNER: &str =
    "/** This file is automatically generated by Flamme. Do not edit. */";

// ---------------------------------------------------------------------------
// JSON values (`JSON.stringify(value, null, 2)`)
// ---------------------------------------------------------------------------

/// A JSON value in JavaScript object key order, so `manifest.json` and
/// `tsconfig.json` can be printed exactly as `JSON.stringify` prints them.
pub(crate) enum Json {
    /// `true` / `false`
    Bool(bool),
    /// An integer.
    Int(i64),
    /// A string.
    Str(String),
    /// An array.
    Arr(Vec<Json>),
    /// An object, its entries in JavaScript own-key order.
    Obj(Vec<(String, Json)>),
}

/// `JSON.stringify(value, null, 2)`, byte for byte.
pub(crate) fn json_pretty(value: &Json) -> String {
    let mut out = String::new();
    write_json(value, 0, &mut out);
    out
}

/// Appends one JSON value at `depth`.
fn write_json(value: &Json, depth: usize, out: &mut String) {
    match value {
        Json::Bool(value) => out.push_str(if *value { "true" } else { "false" }),
        Json::Int(value) => out.push_str(&value.to_string()),
        Json::Str(value) => out.push_str(&json_string(value)),
        Json::Arr(items) => {
            if items.is_empty() {
                out.push_str("[]");
                return;
            }
            out.push_str("[\n");
            for (index, item) in items.iter().enumerate() {
                if index > 0 {
                    out.push_str(",\n");
                }
                out.push_str(&"  ".repeat(depth + 1));
                write_json(item, depth + 1, out);
            }
            out.push('\n');
            out.push_str(&"  ".repeat(depth));
            out.push(']');
        }
        Json::Obj(entries) => {
            if entries.is_empty() {
                out.push_str("{}");
                return;
            }
            out.push_str("{\n");
            for (index, (key, entry)) in entries.iter().enumerate() {
                if index > 0 {
                    out.push_str(",\n");
                }
                out.push_str(&"  ".repeat(depth + 1));
                out.push_str(&json_string(key));
                out.push_str(": ");
                write_json(entry, depth + 1, out);
            }
            out.push('\n');
            out.push_str(&"  ".repeat(depth));
            out.push('}');
        }
    }
}

// ---------------------------------------------------------------------------
// Literal printer
// ---------------------------------------------------------------------------

/// One node of the artifact literal.
enum Lit {
    /// Verbatim text.
    Raw(String),
    /// A JSON string.
    Str(String),
    /// A number.
    Num(f64),
    /// A boolean.
    Bool(bool),
    /// An object.
    Obj(Vec<LitEntry>),
    /// An array.
    Arr(Vec<Lit>),
}

/// One object entry of the artifact literal.
struct LitEntry {
    /// The key.
    key: String,
    /// The value.
    value: Lit,
    /// Emit a blank line before this entry (unless it is the first of its object).
    sep: bool,
}

/// A raw literal.
fn raw(text: impl Into<String>) -> Lit {
    Lit::Raw(text.into())
}
/// A string literal.
fn str_lit(value: impl Into<String>) -> Lit {
    Lit::Str(value.into())
}
/// A number literal.
fn num_lit(value: i64) -> Lit {
    Lit::Num(value as f64)
}
/// A boolean literal.
fn bool_lit(value: bool) -> Lit {
    Lit::Bool(value)
}
/// An object literal.
fn obj(entries: Vec<LitEntry>) -> Lit {
    Lit::Obj(entries)
}
/// An array literal.
fn arr(items: Vec<Lit>) -> Lit {
    Lit::Arr(items)
}
/// An entry.
fn entry(key: &str, value: Lit) -> LitEntry {
    LitEntry { key: key.to_string(), value, sep: false }
}
/// An entry preceded by a blank line.
fn sep_entry(key: &str, value: Lit) -> LitEntry {
    LitEntry { key: key.to_string(), value, sep: true }
}

/// The four-space indentation unit of the literal printer.
const INDENT: &str = "    ";

/// Renders one literal at `depth`.
fn serialize(lit: &Lit, depth: usize) -> String {
    match lit {
        Lit::Raw(text) => text.clone(),
        Lit::Str(value) => json_string(value),
        Lit::Num(value) => js_number(*value),
        Lit::Bool(value) => value.to_string(),
        Lit::Arr(items) => {
            if items.is_empty() {
                return "[]".into();
            }
            if items.iter().all(|item| !matches!(item, Lit::Obj(_) | Lit::Arr(_))) {
                let parts: Vec<String> =
                    items.iter().map(|item| serialize(item, depth)).collect();
                return format!("[{}]", parts.join(", "));
            }
            let parts: Vec<String> = items
                .iter()
                .map(|item| format!("{}{},", INDENT.repeat(depth + 1), serialize(item, depth + 1)))
                .collect();
            format!("[\n{}\n{}]", parts.join("\n"), INDENT.repeat(depth))
        }
        Lit::Obj(entries) => {
            if entries.is_empty() {
                return "{}".into();
            }
            let mut lines: Vec<String> = Vec::new();
            for (index, item) in entries.iter().enumerate() {
                if index > 0 && item.sep {
                    lines.push(String::new());
                }
                lines.push(format!(
                    "{}{}: {},",
                    INDENT.repeat(depth + 1),
                    json_string(&item.key),
                    serialize(&item.value, depth + 1)
                ));
            }
            format!("{{\n{}\n{}}}", lines.join("\n"), INDENT.repeat(depth))
        }
    }
}

/// The JavaScript `String(number)` rendering, which is what `serialize` writes.
fn js_number(value: f64) -> String {
    if value.is_nan() {
        return "NaN".into();
    }
    if value == f64::INFINITY {
        return "Infinity".into();
    }
    if value == f64::NEG_INFINITY {
        return "-Infinity".into();
    }
    if value == 0.0 {
        return "0".into();
    }
    let negative = value < 0.0;
    let magnitude = value.abs();
    // `{:e}` prints the shortest round-tripping digits, which is the digit string
    // the ECMAScript number-to-string algorithm works from.
    let exponential = format!("{magnitude:e}");
    let (mantissa, exponent) = exponential.split_once('e').expect("exponent form");
    let digits: String = mantissa.chars().filter(|character| *character != '.').collect();
    let digits = digits.trim_end_matches('0');
    let digits = if digits.is_empty() { "0" } else { digits };
    let length = digits.len() as i64;
    let point = exponent.parse::<i64>().unwrap_or(0) + 1;
    let text = if length <= point && point <= 21 {
        format!("{digits}{}", "0".repeat((point - length) as usize))
    } else if 0 < point && point <= 21 {
        format!("{}.{}", &digits[..point as usize], &digits[point as usize..])
    } else if -6 < point && point <= 0 {
        format!("0.{}{}", "0".repeat((-point) as usize), digits)
    } else {
        let sign = if point - 1 >= 0 { "+" } else { "-" };
        let exponent_text = (point - 1).abs();
        if length == 1 {
            format!("{digits}e{sign}{exponent_text}")
        } else {
            format!("{}.{}e{sign}{exponent_text}", &digits[..1], &digits[1..])
        }
    };
    if negative { format!("-{text}") } else { text }
}

/// A plain JSON value as a literal.
fn literal_to_text(value: &serde_json::Value, depth: usize) -> Lit {
    match value {
        serde_json::Value::String(text) => str_lit(text.clone()),
        serde_json::Value::Number(number) => Lit::Num(number.as_f64().unwrap_or(0.0)),
        serde_json::Value::Bool(value) => bool_lit(*value),
        serde_json::Value::Null => raw("null"),
        serde_json::Value::Array(items) => {
            arr(items.iter().map(|item| literal_to_text(item, depth)).collect())
        }
        serde_json::Value::Object(fields) => obj(
            fields
                .iter()
                .map(|(key, entry)| entry_of(key, literal_to_text(entry, depth + 1)))
                .collect(),
        ),
    }
}

/// An entry with a runtime key.
fn entry_of(key: &str, value: Lit) -> LitEntry {
    LitEntry { key: key.to_string(), value, sep: false }
}

/// A GraphQL value in the artifact's flat encoding (§3.2).
fn graphql_value_lit(value: &GraphQLValue) -> Lit {
    match value {
        GraphQLValue::Variable { name } => obj(vec![
            entry("kind", str_lit("Variable")),
            entry("name", str_lit(name.clone())),
        ]),
        GraphQLValue::BooleanValue { value } => obj(vec![
            entry("kind", str_lit("BooleanValue")),
            entry("value", bool_lit(*value)),
        ]),
        GraphQLValue::NullValue => obj(vec![entry("kind", str_lit("NullValue"))]),
        GraphQLValue::ListValue { values } => obj(vec![
            entry("kind", str_lit("ListValue")),
            entry("values", arr(values.iter().map(graphql_value_lit).collect())),
        ]),
        GraphQLValue::ObjectValue { fields } => {
            let mut keys: Vec<&str> = fields.keys();
            keys.sort_by(|a, b| compare_names(a, b));
            obj(vec![
                entry("kind", str_lit("ObjectValue")),
                entry(
                    "fields",
                    obj(keys
                        .into_iter()
                        .map(|name| {
                            entry_of(
                                name,
                                graphql_value_lit(
                                    fields.get(name).expect("key from keys()"),
                                ),
                            )
                        })
                        .collect()),
                ),
            ])
        }
        other => obj(vec![
            entry("kind", str_lit(graphql_value_kind(other))),
            entry("value", str_lit(graphql_value_text(other))),
        ]),
    }
}

/// The `kind` string of a scalar `GraphQLValue`.
fn graphql_value_kind(value: &GraphQLValue) -> &'static str {
    match value {
        GraphQLValue::IntValue { .. } => "IntValue",
        GraphQLValue::FloatValue { .. } => "FloatValue",
        GraphQLValue::StringValue { .. } => "StringValue",
        GraphQLValue::EnumValue { .. } => "EnumValue",
        _ => "NullValue",
    }
}

/// The `value` string of a scalar `GraphQLValue`.
fn graphql_value_text(value: &GraphQLValue) -> String {
    match value {
        GraphQLValue::IntValue { value }
        | GraphQLValue::FloatValue { value }
        | GraphQLValue::StringValue { value }
        | GraphQLValue::EnumValue { value } => value.clone(),
        _ => String::new(),
    }
}

/// One selection, its field and fragment maps sorted by key.
fn selection_lit(selection: &SubscriptionSelection) -> Lit {
    let mut fields: Vec<(&str, &FieldSpec)> = selection.fields.iter().collect();
    fields.sort_by(|a, b| compare_names(a.0, b.0));
    let mut fragments: Vec<(&str, &FragmentSpec)> = selection.fragments.iter().collect();
    fragments.sort_by(|a, b| compare_names(a.0, b.0));
    let mut entries: Vec<LitEntry> = vec![entry(
        "fields",
        obj(fields
            .iter()
            .enumerate()
            .map(|(index, (name, field))| LitEntry {
                key: (*name).to_string(),
                value: field_lit(field),
                sep: index > 0,
            })
            .collect()),
    )];
    if !fragments.is_empty() {
        entries.push(sep_entry(
            "fragments",
            obj(fragments
                .iter()
                .enumerate()
                .map(|(index, (name, fragment))| LitEntry {
                    key: (*name).to_string(),
                    value: fragment_lit(fragment),
                    sep: index > 0,
                })
                .collect()),
        ));
    }
    obj(entries)
}

/// One fragment spread.
fn fragment_lit(spec: &FragmentSpec) -> Lit {
    let mut keys: Vec<&str> = spec.arguments.keys();
    keys.sort_by(|a, b| compare_names(a, b));
    let mut entries: Vec<LitEntry> = vec![entry(
        "arguments",
        obj(keys
            .into_iter()
            .map(|name| {
                entry_of(name, graphql_value_lit(spec.arguments.get(name).expect("key from keys()")))
            })
            .collect()),
    )];
    if spec.loading == Some(true) {
        entries.push(entry("loading", bool_lit(true)));
    }
    if let Some(when) = &spec.when {
        if !when.is_empty() {
            entries.push(entry(
                "when",
                arr(when
                    .iter()
                    .map(|condition| {
                        obj(vec![
                            entry("variable", str_lit(condition.variable.clone())),
                            entry("polarity", bool_lit(condition.polarity)),
                        ])
                    })
                    .collect()),
            ));
        }
    }
    if let Some(defer) = &spec.defer {
        entries.push(sep_entry("defer", deferred_lit(defer)));
    }
    obj(entries)
}

/// One field.
fn field_lit(spec: &FieldSpec) -> Lit {
    let mut entries: Vec<LitEntry> = vec![
        entry("type", str_lit(spec.type_name.clone())),
        entry("modifiers", str_lit(spec.modifiers.clone())),
        entry("keyRaw", str_lit(spec.key_raw.clone())),
    ];
    if let Some(nullable) = spec.nullable {
        entries.push(entry("nullable", bool_lit(nullable)));
    }
    if spec.required == Some(true) {
        entries.push(entry("required", bool_lit(true)));
    }
    // `@optimisticKey` marks the field whose value is a stand-in until the server
    // answers; the runtime stamps a temporary id and remaps every reference when
    // the confirmed payload supplies the real one.
    if spec.optimistic_key == Some(true) {
        entries.push(entry("optimisticKey", bool_lit(true)));
    }
    if spec.abstract_has_required == Some(true) {
        entries.push(entry("abstractHasRequired", bool_lit(true)));
    }
    // §9.2: an abstract field's concrete branch selections. The writer keys a composite payload by
    // its concrete type, which it can only do with the branch map (`concreteType` in `write.ts`),
    // so a companion rooted at an interface (`node(id:) { ... on User }`) without it writes the
    // page under the interface's record and the fragment never sees it (`review-f7`).
    if spec.abstract_ == Some(true) {
        if let Some(branches) = &spec.abstract_fields {
            if !branches.is_empty() {
                let mut names: Vec<&str> = branches.keys();
                names.sort_by(|a, b| compare_names(a, b));
                entries.push(entry("abstract", bool_lit(true)));
                entries.push(entry(
                    "abstractFields",
                    obj(names
                        .into_iter()
                        .enumerate()
                        .map(|(index, name)| LitEntry {
                            key: name.to_string(),
                            value: selection_lit(
                                branches.get(name).expect("key from keys()"),
                            ),
                            sep: index > 0,
                        })
                        .collect()),
                ));
            }
        }
    }
    let early_loading = spec
        .loading
        .as_ref()
        .map(|loading| loading.list.is_some())
        .unwrap_or(false);
    if spec.selection.is_some() && !early_loading {
        entries.push(sep_entry(
            "selection",
            selection_lit(spec.selection.as_ref().expect("selection present")),
        ));
    }
    if let Some(loading) = &spec.loading {
        let mut loading_entries: Vec<LitEntry> = vec![entry("kind", str_lit(loading.kind.clone()))];
        if let Some(list) = &loading.list {
            loading_entries.push(entry(
                "list",
                obj(vec![
                    entry("depth", num_lit(list.depth)),
                    entry("count", num_lit(list.count)),
                ]),
            ));
        }
        entries.push(LitEntry {
            key: "loading".into(),
            value: obj(loading_entries),
            sep: spec.selection.is_some() && !early_loading,
        });
    }
    if !is_injected_typename(spec) {
        entries.push(entry("visible", bool_lit(spec.visible == Some(true))));
    }
    if spec.selection.is_some() && early_loading {
        entries.push(sep_entry(
            "selection",
            selection_lit(spec.selection.as_ref().expect("selection present")),
        ));
    }
    if let Some(list) = &spec.list {
        let mut list_entries = vec![
            entry("name", str_lit(list.name.clone())),
            entry("connection", bool_lit(list.connection)),
            entry("type", str_lit(list.type_name.clone())),
        ];
        // §5: `@includeListID` puts the opaque `__id` on the read value, so the list
        // spec is what tells the reader to stamp it.
        if list.include_list_id == Some(true) {
            list_entries.push(entry("includeListID", bool_lit(true)));
        }
        entries.push(entry("list", obj(list_entries)));
    }
    if let Some(filters) = &spec.filters {
        let mut keys: Vec<&str> = filters.keys();
        keys.sort_by(|a, b| compare_names(a, b));
        entries.push(entry(
            "filters",
            obj(keys
                .into_iter()
                .map(|name| {
                    entry_of(name, graphql_value_lit(filters.get(name).expect("key from keys()")))
                })
                .collect()),
        ));
    }
    if let Some(defer) = &spec.defer {
        entries.push(sep_entry("defer", deferred_lit(defer)));
    }
    if let Some(pagination) = &spec.pagination {
        let mut pagination_entries: Vec<LitEntry> = vec![
            entry(
                "path",
                arr(pagination.path.iter().map(|part| str_lit(part.clone())).collect()),
            ),
            entry("method", str_lit(pagination.method.clone())),
            entry("mode", str_lit(pagination.mode.clone())),
            entry("pageSize", num_lit(pagination.page_size)),
            entry("embedded", bool_lit(pagination.embedded)),
            entry("targetType", str_lit(pagination.target_type.clone())),
            entry("paginated", bool_lit(pagination.paginated)),
            entry("direction", str_lit(pagination.direction.clone())),
            entry("supportsForward", bool_lit(pagination.supports_forward)),
            entry("supportsBackward", bool_lit(pagination.supports_backward)),
        ];
        if let Some(cursor_type) = &pagination.cursor_type {
            pagination_entries.push(entry("cursorType", str_lit(cursor_type.clone())));
        }
        entries.push(entry("pagination", obj(pagination_entries)));
    }
    if let Some(updates) = &spec.updates {
        entries.push(entry(
            "updates",
            arr(updates.iter().map(|update| str_lit(update.clone())).collect()),
        ));
    }
    if let Some(directives) = &spec.directives {
        if !directives.is_empty() {
            entries.push(entry(
                "directives",
                arr(directives
                    .iter()
                    .map(|directive| {
                        let mut keys: Vec<&str> = directive.arguments.keys();
                        keys.sort_by(|a, b| compare_names(a, b));
                        obj(vec![
                            entry("name", str_lit(directive.name.clone())),
                            entry(
                                "arguments",
                                obj(keys
                                    .into_iter()
                                    .map(|name| {
                                        entry_of(
                                            name,
                                            graphql_value_lit(
                                                directive
                                                    .arguments
                                                    .get(name)
                                                    .expect("key from keys()"),
                                            ),
                                        )
                                    })
                                    .collect()),
                            ),
                        ])
                    })
                    .collect()),
            ));
        }
    }
    if let Some(operations) = &spec.operations {
        if !operations.is_empty() {
            entries.push(entry(
                "operations",
                arr(operations
                    .iter()
                    .map(|operation| {
                        let mut entries = vec![
                            entry("action", str_lit(operation.action.clone())),
                            entry("list", str_lit(operation.list.clone())),
                        ];
                        if let Some(position) = &operation.position {
                            entries.push(entry("position", str_lit(position.clone())));
                        }
                        if let Some(target) = &operation.target {
                            entries.push(entry("target", str_lit(target.clone())));
                        }
                        // §4: the filters the operation applies under, both polarities.
                        if let Some(when) = &operation.when {
                            let mut when_entries: Vec<LitEntry> = Vec::new();
                            if !when.must.is_empty() {
                                let mut keys: Vec<&str> = when.must.keys();
                                keys.sort_by(|a, b| compare_names(a, b));
                                when_entries.push(entry(
                                    "must",
                                    obj(keys
                                        .into_iter()
                                        .map(|name| {
                                            entry_of(
                                                name,
                                                graphql_value_lit(
                                                    when.must.get(name).expect("key from keys()"),
                                                ),
                                            )
                                        })
                                        .collect()),
                                ));
                            }
                            if !when.must_not.is_empty() {
                                let mut keys: Vec<&str> = when.must_not.keys();
                                keys.sort_by(|a, b| compare_names(a, b));
                                when_entries.push(entry(
                                    "mustNot",
                                    obj(keys
                                        .into_iter()
                                        .map(|name| {
                                            entry_of(
                                                name,
                                                graphql_value_lit(
                                                    when
                                                        .must_not
                                                        .get(name)
                                                        .expect("key from keys()"),
                                                ),
                                            )
                                        })
                                        .collect()),
                                ));
                            }
                            entries.push(entry("when", obj(when_entries)));
                        }
                        // §5: the opaque list id `@listID(value:)` names.
                        if let Some(list_id) = &operation.list_id {
                            entries.push(entry("listID", graphql_value_lit(list_id)));
                        }
                        obj(entries)
                    })
                    .collect()),
            ));
        }
    }
    obj(entries)
}

/// The `input` member of an artifact.
fn input_lit(input: &InputObject) -> Lit {
    let mut field_keys: Vec<&str> = input.fields.keys();
    field_keys.sort_by(|a, b| compare_names(a, b));
    let mut type_keys: Vec<&str> = input.types.keys();
    type_keys.sort_by(|a, b| compare_names(a, b));
    let mut default_keys: Vec<&str> = input.defaults.keys();
    default_keys.sort_by(|a, b| compare_names(a, b));
    obj(vec![
        entry(
            "fields",
            obj(field_keys
                .into_iter()
                .map(|name| {
                    entry_of(
                        name,
                        str_lit(input.fields.get(name).expect("key from keys()").clone()),
                    )
                })
                .collect()),
        ),
        sep_entry(
            "types",
            obj(type_keys
                .into_iter()
                .map(|name| {
                    let fields = input.types.get(name).expect("key from keys()");
                    let mut inner: Vec<&str> = fields.keys();
                    inner.sort_by(|a, b| compare_names(a, b));
                    entry_of(
                        name,
                        obj(inner
                            .into_iter()
                            .map(|field| {
                                entry_of(
                                    field,
                                    str_lit(fields.get(field).expect("key from keys()").clone()),
                                )
                            })
                            .collect()),
                    )
                })
                .collect()),
        ),
        sep_entry(
            "defaults",
            obj(default_keys
                .into_iter()
                .map(|name| {
                    entry_of(
                        name,
                        literal_to_text(
                            input.defaults.get(name).expect("key from keys()"),
                            3,
                        ),
                    )
                })
                .collect()),
        ),
        sep_entry("runtimeScalars", obj(Vec::new())),
    ])
}

/// One recorded `@defer`/`@stream` target, as the artifact literal spells it (§7.13).
fn deferred_lit(spec: &DeferredSpec) -> Lit {
    let mut entries: Vec<LitEntry> = vec![
        entry("label", str_lit(spec.label.clone())),
        entry("kind", str_lit(spec.kind.clone())),
        sep_entry(
            "path",
            arr(spec.path.iter().map(|part| str_lit(part.clone())).collect()),
        ),
    ];
    if let Some(fragment) = &spec.fragment {
        entries.push(entry("fragment", str_lit(fragment.clone())));
    }
    if let Some(initial_count) = spec.initial_count {
        entries.push(entry("initialCount", num_lit(initial_count)));
    }
    if let Some(condition) = &spec.if_value {
        entries.push(sep_entry("if", graphql_value_lit(condition)));
    }
    obj(entries)
}

/// The artifact literal itself.
fn artifact_lit(document: &IrDocument) -> Lit {
    let is_query = document.kind == ArtifactKind::Query;
    let mut entries: Vec<LitEntry> = vec![
        entry("name", str_lit(document.name.clone())),
        entry("kind", str_lit(document.kind.as_str())),
        entry("hash", str_lit(document.hash.clone())),
        entry(
            "raw",
            raw(format!("`{}`", escape_template_literal(&document.raw))),
        ),
        sep_entry("rootType", str_lit(document.root_type.clone())),
        entry("stripVariables", raw("[] as Array<string>")),
    ];
    if document.optimistic_keys == Some(true) {
        entries.push(entry("optimisticKeys", bool_lit(true)));
    }
    entries.push(sep_entry("selection", selection_lit(&document.selection)));
    if document.kind != ArtifactKind::Fragment || !document.input.fields.is_empty() {
        entries.push(sep_entry("input", input_lit(&document.input)));
    }
    if let Some(refetch) = &document.refetch {
        entries.push(sep_entry(
            "refetch",
            obj(vec![
                entry(
                    "path",
                    arr(refetch.path.iter().map(|part| str_lit(part.clone())).collect()),
                ),
                entry("method", str_lit(refetch.method.clone())),
                entry("mode", str_lit(refetch.mode.clone())),
                entry("pageSize", num_lit(refetch.page_size)),
                entry("embedded", bool_lit(refetch.embedded)),
                entry("targetType", str_lit(refetch.target_type.clone())),
                entry("paginated", bool_lit(refetch.paginated)),
                entry("direction", str_lit(refetch.direction.clone())),
            ]),
        ));
    }
    // §3: a paginated fragment's page requests are sent as its companion query; the
    // generated module carries it so `usePaginatedFragment` has the document to send.
    if let Some(companion) = &document.pagination_companion {
        entries.push(sep_entry("paginationArtifact", raw("paginationArtifact")));
        let _ = companion;
    }
    entries.push(sep_entry("pluginData", obj(Vec::new())));
    if let Some(deferred) = &document.deferred {
        if !deferred.is_empty() {
            // §7.13: the recorded `@defer`/`@stream` targets, in source order. The directive itself is in
            // `raw` too (the server applies it); this is what the runtime merges a patch against.
            entries.push(sep_entry(
                "deferred",
                arr(deferred.iter().map(deferred_lit).collect()),
            ));
        }
    }
    if let Some(enable_loading_state) = &document.enable_loading_state {
        entries.push(entry("enableLoadingState", str_lit(enable_loading_state.clone())));
    }
    if is_query {
        entries.push(entry(
            "policy",
            str_lit(
                document
                    .policy
                    .map(|policy| policy.as_str())
                    .unwrap_or("CacheOrNetwork"),
            ),
        ));
        entries.push(entry("partial", bool_lit(document.partial.unwrap_or(false))));
    }
    obj(entries)
}

/// Escapes a document for inclusion in a template literal: backslashes first, then
/// backticks, then `${`. Missing the last one makes the emitted `raw` interpolate
/// (or throw `ReferenceError`) when the artifact module is imported, while `hash`
/// keeps the digest of the real document (F1).
fn escape_template_literal(text: &str) -> String {
    text.replace('\\', "\\\\").replace('`', "\\`").replace("${", "\\${")
}

/// Trims the trailing comma of the last line, if there is one.
fn trim_last_comma(lines: &mut [String]) {
    if let Some(last) = lines.last_mut() {
        if last.ends_with(',') {
            last.pop();
        }
    }
}

// ---------------------------------------------------------------------------
// The artifact module
// ---------------------------------------------------------------------------

/// One artifact module.
pub fn emit_artifact(document: &IrDocument, schema: &SchemaIndex, config: &RustConfig) -> String {
    let name = &document.name;
    let is_fragment = document.kind == ArtifactKind::Fragment;
    let type_context = TypeContext { schema, config, document };

    // Render the type blocks first: the import line depends on which runtime types
    // the file actually references (ruling: artifacts import what they use).
    let key_block = if is_fragment {
        let mut lines: Vec<String> = vec![
            "/**".into(),
            " * The masked marker a parent must carry to hand this fragment to a child. A plain object shape"
                .into(),
            " * (no conditional/mapped type) because `defineProps<...>()` resolves through a fixed node set"
                .into(),
            " * (§8.4, §8.9), and a `FragmentReference` payload rather than gql.tada's all-optional brand, so"
                .into(),
            " * `{}` and a raw unmasked object are both rejected.".into(),
            " */".into(),
            format!("export type {name}$key = {{"),
            "\treadonly \" $fragments\": {".into(),
        ];
        lines.extend(key_refs(document).into_iter().map(|reference| {
            format!("\t\treadonly {reference}: FragmentRef;")
        }));
        lines.push("\t};".into());
        lines.push("};".into());
        lines.push(String::new());
        lines.push(
            "/** The fragment's own view: what the component that declares it may read. */".into(),
        );
        lines.join("\n")
    } else {
        String::new()
    };
    let data_block = if is_fragment {
        format!(
            "export type {name}$data = {};",
            render_type(
                &document.selection,
                &document.root_type,
                Mode::Data,
                &type_context,
                0,
                true,
                false,
                false,
                None,
                true,
            )
        )
    } else {
        String::new()
    };
    let handle_block = if is_fragment {
        format!("export type {name} = Artifact<'fragment', {name}$data, never, {name}$key>")
    } else {
        format!(
            "export type {name} = Artifact<'{}', {name}$result, {name}$input, never>",
            document.kind.as_str()
        )
    };
    let result_block = if is_fragment {
        String::new()
    } else {
        format!("export type {name}$result = {};", result_type(document, &type_context))
    };
    let input_block = if is_fragment {
        String::new()
    } else {
        format!("export type {name}$input = {};", input_type(&document.input, &type_context))
    };
    let unmasked_block = if is_fragment {
        String::new()
    } else {
        format!(
            "export type {name}$unmasked = {};",
            render_type(
                &document.selection,
                &document.root_type,
                Mode::Unmasked,
                &type_context,
                0,
                false,
                false,
                false,
                None,
                true,
            )
        )
    };
    let optimistic_block = if !is_fragment && document.kind == ArtifactKind::Mutation {
        format!(
            "export type {name}$optimistic = {};",
            render_type(
                &document.selection,
                &document.root_type,
                Mode::Optimistic,
                &type_context,
                0,
                false,
                false,
                false,
                None,
                true,
            )
        )
    } else {
        String::new()
    };
    let deferred_block = emit_deferred_helpers(document, name, is_fragment);
    let body = [
        &key_block,
        &data_block,
        &result_block,
        &input_block,
        &unmasked_block,
        &optimistic_block,
        &deferred_block,
        &handle_block,
    ]
    .into_iter()
    .filter(|block| !block.is_empty())
    .cloned()
    .collect::<Vec<String>>()
    .join("\n\n");
    // `emitted_imports` reads the keys of `schema.inputTypes` only, so the artifact
    // projection passes the same keys with the unused values blanked (TS reads
    // `Object.keys(inputTypes)`).
    let input_names: JsObject<String> = JsObject::from_pairs(
        schema.input_types.keys().into_iter().map(|name| (name.to_string(), String::new())),
    );
    let imports = emitted_imports(&body, config, &input_names);

    let serialized = serialize(&artifact_lit(document), 0);
    let all_lines: Vec<String> = serialized.split('\n').map(str::to_string).collect();
    let mut artifact_lines = if all_lines.len() >= 2 {
        all_lines[1..all_lines.len() - 1].to_vec()
    } else {
        Vec::new()
    };
    trim_last_comma(&mut artifact_lines);

    let mut lines: Vec<String> = vec![
        GENERATED_BANNER.to_string(),
        format!("// source: {}", document.source),
    ];
    if let Some(companion) = &document.pagination_companion {
        lines.push(format!(
            "import paginationArtifact from './{companion}.js'"
        ));
    }
    lines.extend(imports);
    lines.push(String::new());
    lines.push("const artifact = {".into());
    lines.extend(artifact_lines);
    lines.push("} as const".into());
    lines.push(String::new());
    lines.push(format!("export type {name}$artifact = typeof artifact"));
    lines.push(String::new());

    if is_fragment {
        lines.push(key_block);
        lines.push(String::new());
        lines.push(data_block);
        lines.push(String::new());
        lines.push(handle_block);
        lines.push(String::new());
        lines.push(format!("const document: {name} = artifact as unknown as {name}"));
        lines.push(String::new());
        lines.push("export default document".into());
        return format!("{}\n", lines.join("\n"));
    }

    lines.push(format!(
        "/** Runtime handle for `{name}`. This is what a `.gql` import or the generated barrel yields. */"
    ));
    lines.push(handle_block);
    lines.push(String::new());
    lines.push(result_block);
    lines.push(String::new());
    lines.push(input_block);
    lines.push(String::new());
    lines.push(unmasked_block);
    if !optimistic_block.is_empty() {
        lines.push(String::new());
        lines.push(optimistic_block);
    }
    if !deferred_block.is_empty() {
        lines.push(String::new());
        lines.push(deferred_block);
    }
    lines.push(String::new());
    lines.push(format!("const document: {name} = artifact as unknown as {name}"));
    lines.push(String::new());
    lines.push("export default document".into());
    format!("{}\n", lines.join("\n"))
}

/// The `@defer`/`@stream` helpers of one artifact (§7.13).
fn emit_deferred_helpers(document: &IrDocument, name: &str, is_fragment: bool) -> String {
    let deferred = document.deferred.clone().unwrap_or_default();
    if deferred.is_empty() {
        return String::new();
    }
    let base_type = if is_fragment { format!("{name}$data") } else { format!("{name}$unmasked") };
    let mut used: Vec<String> = Vec::new();
    let mut blocks: Vec<String> = Vec::new();
    for spec in &deferred {
        let helper = deferred_helper_name(&spec.label, &mut used);
        let target = deferred_target(document, spec);
        let path_type = path_object_type(&base_type, &document.selection, &target.object_path);
        let result_type_name = if is_fragment { format!("{name}$data") } else { format!("{name}$result") };
        let kind_label = if spec.kind == "list" { "stream" } else { "defer" };
        let mut first: Vec<String> = vec![
            "/**".into(),
            format!(
                " * `true` once the incremental data for `@{kind_label}(label: \"{}\")` has been merged into",
                spec.label
            ),
        ];
        if spec.kind == "list" {
            first.push(
                " * this result. Until then the list holds the items the server already sent, and".into(),
            );
            first.push(" * `result.hasNext` says whether more of them are on the way.".into());
        } else {
            first.push(
                " * this result. Until then the target's fields are optional (or, for a masked spread, absent by"
                    .into(),
            );
            first.push(
                " * construction), and `result.hasNext` says whether more patches are still on the way."
                    .into(),
            );
        }
        first.push(" */".into());
        first.push(format!(
            "export function is{helper}Ready(result: QueryResult<{result_type_name}>): boolean {{"
        ));
        first.push(format!("\treturn result.deferred[{}] === 'ready';", json_string(&spec.label)));
        first.push("}".into());
        blocks.push(first.join("\n"));
        if target.keys.is_empty() {
            continue;
        }
        let present = target
            .keys
            .iter()
            .map(|key| {
                format!(
                    "\treadonly {}: {};",
                    quote_if_needed(key),
                    deferred_key_type(&path_type, key)
                )
            })
            .collect::<Vec<String>>()
            .join("\n");
        // A union path (`@defer` inside a union or interface branch) needs the `in` check: the key is
        // not a member of every branch, so a bare indexed read is not valid TypeScript.
        let checks = target
            .keys
            .iter()
            .map(|key| {
                if path_type.union {
                    format!(
                        "{} in value && value[{}] !== undefined",
                        json_string(key),
                        json_string(key)
                    )
                } else {
                    format!("value[{}] !== undefined", json_string(key))
                }
            })
            .collect::<Vec<String>>()
            .join(" && ");
        let object_path =
            if target.object_path.is_empty() { "<root>".to_string() } else { target.object_path.join(".") };
        blocks.push(
            vec![
                "/**".into(),
                format!(
                    " * `true` when every key `@{kind_label}(label: \"{}\")` delivers is present on the object",
                    spec.label
                ),
                format!(
                    " * at `{object_path}`. Accepts the incremental view (`Incremental<T>`, what a"
                ),
                " * read produces before the patch) and narrows it to the loaded one. Use it on an unmasked read;"
                    .into(),
                format!(
                    " * a masked spread keeps these fields out of the parent's own type, and `is{helper}Ready` is the"
                ),
                " * predicate there.".into(),
                " */".into(),
                format!("export function has{helper}("),
                format!(
                    "\tvalue: Incremental<{}>,\n): value is {} & {{\n{present}\n}} {{",
                    path_type.expression, path_type.expression
                ),
                format!("\treturn {checks};"),
                "}".into(),
            ]
            .join("\n"),
        );
    }
    blocks.join("\n\n")
}

/// The object a target's fields live on and the response keys that arrive with its patch.
struct DeferredTarget {
    /// Response-key path of the object.
    object_path: Vec<String>,
    /// The keys the patch delivers on that object.
    keys: Vec<String>,
}

/// The object a target's fields live on and the response keys that arrive with its patch.
fn deferred_target(document: &IrDocument, spec: &DeferredSpec) -> DeferredTarget {
    if spec.kind == "list" {
        let field = spec.path.last().cloned();
        return DeferredTarget {
            object_path: spec.path[..spec.path.len().saturating_sub(1)].to_vec(),
            keys: field.into_iter().collect(),
        };
    }
    let selection = selection_at_path(&document.selection, &spec.path);
    let mut keys: Vec<String> = Vec::new();
    if let Some(selection) = selection {
        for (key, field) in selection.fields.iter() {
            if field.defer.as_ref().map(|defer| defer.label == spec.label).unwrap_or(false) {
                keys.push(key.to_string());
            }
        }
    }
    DeferredTarget { object_path: spec.path.clone(), keys }
}

/// The selection a response-key path resolves to, or `None` when it leaves the tree.
fn selection_at_path<'a>(
    selection: &'a SubscriptionSelection,
    path: &[String],
) -> Option<&'a SubscriptionSelection> {
    let mut current: Option<&SubscriptionSelection> = Some(selection);
    for part in path {
        let field = current.and_then(|current| current.fields.get(part));
        current = field.and_then(|field| field.selection.as_ref());
    }
    current
}

/// The TypeScript type of the object at `path` inside `baseType`, and whether that
/// object is a union of concrete branches (§9.2).
struct PathType {
    /// The TypeScript expression of the object.
    expression: String,
    /// `true` when the object is a union of concrete branches.
    union: bool,
}

/// The TypeScript type of the object at `path` inside `baseType`.
fn path_object_type(
    base_type: &str,
    selection: &SubscriptionSelection,
    path: &[String],
) -> PathType {
    let mut expression = base_type.to_string();
    let mut current: Option<&SubscriptionSelection> = Some(selection);
    for part in path {
        let field = current.and_then(|current| current.fields.get(part));
        let key = json_string(part);
        let access = if is_abstract_selection(current) {
            format!("Extract<{expression}, {{ readonly {}?: unknown }}>[{key}]", quote_if_needed(part))
        } else {
            format!("{expression}[{key}]")
        };
        expression = format!("NonNullable<{access}>");
        if let Some(field) = field {
            if field.modifiers.contains(']') {
                expression = format!("{expression}[number]");
            }
        }
        current = field.and_then(|field| field.selection.as_ref());
    }
    PathType { expression, union: is_abstract_selection(current) }
}

/// True when a selection renders as a union of concrete branches rather than one object type.
fn is_abstract_selection(selection: Option<&SubscriptionSelection>) -> bool {
    selection.map(|selection| !selection.abstract_fields.is_empty()).unwrap_or(false)
}

/// The type one deferred key has on the object at `path_type`, `never` on a branch that lacks it.
fn deferred_key_type(path_type: &PathType, key: &str) -> String {
    let name = quote_if_needed(key);
    if path_type.union {
        format!(
            "NonNullable<Extract<{}, {{ readonly {}?: unknown }}>[{}]>",
            path_type.expression,
            name,
            json_string(key)
        )
    } else {
        format!("NonNullable<{}[{}]>", path_type.expression, json_string(key))
    }
}

/// `evolutionChain` → `EvolutionChain`, `stream_moves` → `StreamMoves`, `0x` → `Defer0x`.
fn deferred_helper_name(label: &str, used: &mut Vec<String>) -> String {
    let pascal = label
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            let first = chars.next().expect("non-empty part").to_ascii_uppercase();
            format!("{first}{}", chars.as_str())
        })
        .collect::<String>();
    let base = if pascal.starts_with(|character: char| character.is_ascii_alphabetic()) {
        pascal
    } else {
        format!("Defer{pascal}")
    };
    let mut candidate = base.clone();
    let mut suffix = 2;
    while used.contains(&candidate) {
        candidate = format!("{base}{suffix}");
        suffix += 1;
    }
    used.push(candidate.clone());
    candidate
}

/// The `import type` lines an artifact needs.
pub fn emitted_imports(
    body: &str,
    config: &RustConfig,
    input_types: &crate::js::JsObject<String>,
) -> Vec<String> {
    let mut runtime = vec!["Artifact"];
    if body.contains("FragmentRef") {
        runtime.push("FragmentRef");
    }
    if body.contains("LoadingType") {
        runtime.push("LoadingType");
    }
    if contains_word_then(body, "Incremental", "<") {
        runtime.push("Incremental");
    }
    if contains_word_then(body, "QueryResult", "<") {
        runtime.push("QueryResult");
    }
    let mut lines = vec![format!("import type {{ {} }} from '@flamme/runtime'", runtime.join(", "))];
    let mut enums = collect_enum_unions(body);
    enums.sort_by(|a, b| compare_names(a, b));
    enums.dedup();
    if !enums.is_empty() {
        let names: Vec<String> = enums.iter().map(|entry| format!("{entry}$options")).collect();
        lines.push(format!(
            "import type {{ {} }} from '../graphql/enums'",
            names.join(", ")
        ));
    }
    let mut scalars: Vec<&crate::config::ScalarConfig> = config
        .scalars
        .values()
        .filter(|scalar| {
            scalar.module.is_some()
                && scalar
                    .type_name
                    .as_deref()
                    .map(is_identifier)
                    .unwrap_or(false)
                && scalar
                    .type_name
                    .as_deref()
                    .map(|name| body.contains(name))
                    .unwrap_or(false)
        })
        .collect();
    scalars.sort_by(|a, b| {
        compare_names(a.type_name.as_deref().unwrap_or(""), b.type_name.as_deref().unwrap_or(""))
    });
    for scalar in scalars {
        let type_name = scalar.type_name.as_deref().unwrap_or("");
        let module = scalar.module.as_deref().unwrap_or("");
        if scalar.default == Some(true) {
            lines.push(format!("import type {type_name} from '{module}'"));
        } else {
            lines.push(format!("import type {{ {type_name} }} from '{module}'"));
        }
    }
    let mut inputs: Vec<&str> = input_types
        .keys()
        .into_iter()
        .filter(|name| is_identifier(name) && contains_word(body, name))
        .collect();
    inputs.sort_by(|a, b| compare_names(a, b));
    if !inputs.is_empty() {
        lines.push(format!(
            "import type {{ {} }} from '../graphql/inputs'",
            inputs.join(", ")
        ));
    }
    lines
}

/// True for a JavaScript `\w` character.
fn is_word_char(character: char) -> bool {
    character.is_ascii_alphanumeric() || character == '_'
}

/// True when `text` contains `word` at a word boundary, immediately followed by `tail`.
fn contains_word_then(text: &str, word: &str, tail: &str) -> bool {
    let mut search = 0;
    while let Some(offset) = text[search..].find(word) {
        let start = search + offset;
        let end = start + word.len();
        let before_ok =
            start == 0 || !is_word_char(text[..start].chars().next_back().expect("char"));
        if before_ok && text[end..].starts_with(tail) {
            return true;
        }
        search = start + 1;
    }
    false
}

/// True when `text` contains `word` with word boundaries on both sides.
fn contains_word(text: &str, word: &str) -> bool {
    let mut search = 0;
    while let Some(offset) = text[search..].find(word) {
        let start = search + offset;
        let end = start + word.len();
        let before_ok =
            start == 0 || !is_word_char(text[..start].chars().next_back().expect("char"));
        let after_ok =
            end == text.len() || !is_word_char(text[end..].chars().next().expect("char"));
        if before_ok && after_ok {
            return true;
        }
        search = start + 1;
    }
    false
}

/// Every `\b(\w+)\$options\b` capture of `body`, in source order.
fn collect_enum_unions(body: &str) -> Vec<String> {
    let mut found: Vec<String> = Vec::new();
    let mut search = 0;
    while let Some(offset) = body[search..].find("$options") {
        let at = search + offset;
        let end = at + "$options".len();
        let after_ok =
            end == body.len() || !is_word_char(body[end..].chars().next().expect("char"));
        if after_ok {
            let before = &body[..at];
            let run_start = before.trim_end_matches(is_word_char).len();
            let start_ok = run_start == 0
                || !is_word_char(before[..run_start].chars().next_back().expect("char"));
            if run_start < at && start_ok {
                found.push(body[run_start..at].to_string());
            }
        }
        search = end;
    }
    found
}

// ---------------------------------------------------------------------------
// Type generation
// ---------------------------------------------------------------------------

/// What the type generator reads.
struct TypeContext<'a> {
    /// The schema index.
    schema: &'a SchemaIndex,
    /// The resolved config.
    config: &'a RustConfig,
    /// The document being emitted.
    document: &'a IrDocument,
}

/// The rendering mode `renderType` is called with.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Mode {
    /// The masked view.
    Masked,
    /// A loading frame.
    Frame,
    /// A fragment's own view.
    Data,
    /// The unmasked flatten.
    Unmasked,
    /// A mutation's optimistic view.
    Optimistic,
}

/// The artifact's decision about a field's outermost nullability.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Outermost {
    /// Follow the schema.
    Schema,
    /// `@required`: non-null.
    NonNull,
    /// The compiler's `nullable: true` mark.
    Nullable,
}

/// The type an empty selection renders to; used to prune invisible subtrees.
const EMPTY_OBJECT: &str = "Record<string, never>";

/// `depth` tabs.
fn tab(depth: usize) -> String {
    "\t".repeat(depth)
}

/// The `$result` alias: the masked flatten, unioned with its loading frame.
fn result_type(document: &IrDocument, context: &TypeContext) -> String {
    let is_fragment = document.kind == ArtifactKind::Fragment;
    let loaded = render_type(
        &document.selection,
        &document.root_type,
        Mode::Masked,
        context,
        0,
        is_fragment,
        false,
        true,
        None,
        true,
    );
    if document.enable_loading_state.is_none() {
        return loaded;
    }
    format!(
        "{loaded} | {}",
        render_type(
            &document.selection,
            &document.root_type,
            Mode::Frame,
            context,
            0,
            false,
            false,
            true,
            None,
            true,
        )
    )
}

/// The `$input` alias of an operation.
fn input_type(input: &InputObject, context: &TypeContext) -> String {
    let mut names: Vec<&str> = input.fields.keys();
    names.sort_by(|a, b| compare_names(a, b));
    if names.is_empty() {
        return EMPTY_OBJECT.to_string();
    }
    let lines: Vec<String> = names
        .into_iter()
        .map(|name| {
            let field_type = input.fields.get(name).cloned().unwrap_or_else(|| "String".into());
            let optional = input.defaults.get(name).is_some() || !field_type.ends_with('!');
            format!(
                "{}readonly {}{}: {};",
                tab(1),
                quote_if_needed(name),
                if optional { "?" } else { "" },
                ts_type_of_type_string(&field_type, Some(context))
            )
        })
        .collect();
    format!("{{\n{}\n}}", lines.join("\n"))
}

/// A name as an object key: bare when it is an identifier, quoted otherwise.
fn quote_if_needed(name: &str) -> String {
    if is_identifier(name) { name.to_string() } else { json_string(name) }
}

/// The immutable fields of the fragment's `$key` alias: own name plus transitive spreads.
fn key_refs(document: &IrDocument) -> Vec<String> {
    let mut names: Vec<String> = vec![document.name.clone()];
    fn walk(
        document: &IrDocument,
        selection: &SubscriptionSelection,
        names: &mut Vec<String>,
    ) {
        for (spread, _) in selection.fragments.iter() {
            if !names.iter().any(|name| name == spread) {
                names.push(spread.to_string());
                if let Some(nested) = fragment_selection_of(document, spread) {
                    walk(document, nested, names);
                }
            }
        }
    }
    walk(document, &document.selection, &mut names);
    names.sort_by(|a, b| compare_names(a, b));
    names
}

/// The named type of a type string, `Unknown` when it does not parse.
fn safe_parse_type(text: &str) -> TypeNode {
    parse_type(text).unwrap_or_else(|_| {
        TypeNode::Named(NamedType { name: Name::synthetic("Unknown"), loc: None })
    })
}

/// Renders one selection as a TypeScript object type.
#[allow(clippy::too_many_arguments)]
fn render_type(
    selection: &SubscriptionSelection,
    type_name: &str,
    mode: Mode,
    context: &TypeContext,
    depth: usize,
    root: bool,
    frame_object: bool,
    top_level: bool,
    branch_type: Option<&str>,
    addressable: bool,
) -> String {
    let abstract_selection = !selection.abstract_fields.is_empty();
    if branch_type.is_none() && abstract_selection {
        return render_abstract_union(
            selection,
            type_name,
            mode,
            context,
            depth,
            root,
            frame_object,
            top_level,
            addressable,
        );
    }
    let mut lines: Vec<String> = Vec::new();
    if let Some(branch) = branch_type {
        lines.push(format!("{}readonly __typename: {};", tab(depth + 1), json_string(branch)));
    }
    for (name, field) in selection.fields.iter() {
        // Only the compiler-injected `__typename` is meta: a user field aliased *to*
        // `__typename` is a normal selected field and renders in every mode (A15).
        let injected = is_injected_typename(field);
        if name == "__typename" && injected && (mode != Mode::Unmasked || branch_type.is_some()) {
            continue;
        }
        if name == "__typename" && injected && branch_type.is_none() && mode == Mode::Unmasked {
            lines.push(format!(
                "{}readonly __typename: {};",
                tab(depth + 1),
                typename_type(type_name, context)
            ));
            continue;
        }
        let rendered = render_field(
            name,
            field,
            mode,
            context,
            depth + 1,
            top_level && context.document.kind != ArtifactKind::Fragment,
            addressable,
        );
        if let Some(rendered) = rendered {
            lines.push(rendered);
        }
    }
    if mode == Mode::Unmasked {
        for (spread, _) in selection.fragments.iter() {
            let nested = fragment_selection_of(context.document, spread);
            let condition = fragment_type_of(context.document, spread);
            let (Some(nested), Some(_condition)) = (nested, condition) else {
                continue;
            };
            let present: Vec<&str> = selection.fields.keys();
            let inlined = inline_selection(nested, &present);
            for (name, field) in inlined.fields.iter() {
                let rendered = render_field(
                    name,
                    field,
                    mode,
                    context,
                    depth + 1,
                    top_level && context.document.kind != ArtifactKind::Fragment,
                    addressable,
                );
                if let Some(rendered) = rendered {
                    lines.push(rendered);
                }
            }
        }
    } else if addressable {
        // A spread on an inlined composite has no record to reference, so it is not promised here; an
        // unmasked read still inlines its fields (above), which is how such a spread stays readable.
        let refs = collect_refs(selection, type_name, context);
        if !refs.is_empty() {
            // §7.1/§8.7: a frame keeps its `FragmentRef`s, so a frame is assignable to a child's `$key`
            // prop; only the child's own read of the not-yet-loaded record is what reports pending (K1c).
            lines.push(format!("{}readonly \" $fragments\": {{", tab(depth + 1)));
            for reference in &refs {
                lines.push(format!("{}{}: FragmentRef;", tab(depth + 2), reference));
            }
            lines.push(format!("{}}};", tab(depth + 1)));
        }
    }
    // The discriminant marks the object that can be either a loaded value or a
    // frame: a fragment's own object, or an operation's root field objects (§8.7).
    if root && (mode == Mode::Masked || mode == Mode::Data) {
        lines.push(format!("{}readonly \" $loadingFrame\"?: undefined;", tab(depth + 1)));
    }
    if frame_object && mode == Mode::Frame {
        lines.push(format!("{}readonly \" $loadingFrame\": true;", tab(depth + 1)));
    }
    if lines.is_empty() {
        return EMPTY_OBJECT.to_string();
    }
    format!("{{\n{}\n{}}}", lines.join("\n"), tab(depth))
}

/// The fragment selection of a document by name (a `Map.get`, last write wins).
fn fragment_selection_of<'a>(
    document: &'a IrDocument,
    name: &str,
) -> Option<&'a SubscriptionSelection> {
    document
        .fragment_selections
        .iter()
        .rev()
        .find(|(key, _)| key == name)
        .map(|(_, selection)| selection)
}

/// The fragment type condition of a document by name (a `Map.get`, last write wins).
fn fragment_type_of<'a>(document: &'a IrDocument, name: &str) -> Option<&'a str> {
    document
        .fragment_types
        .iter()
        .rev()
        .find(|(key, _)| key == name)
        .map(|(_, condition)| condition.as_str())
}

/// The type whose key field a name was injected for (a `Map.get`, last write wins).
fn injected_key_of<'a>(document: &'a IrDocument, name: &str) -> Option<&'a str> {
    document
        .injected_keys
        .iter()
        .rev()
        .find(|(key, _)| key == name)
        .map(|(_, type_name)| type_name.as_str())
}

/// A spread's fields with the parent's keys kept first (the unmasked merge rule).
fn inline_selection(
    selection: &SubscriptionSelection,
    present: &[&str],
) -> SubscriptionSelection {
    let mut fields: JsObject<FieldSpec> = JsObject::new();
    for (name, field) in selection.fields.iter() {
        if present.contains(&name) {
            continue;
        }
        fields.insert(name, field.clone());
    }
    SubscriptionSelection { fields, ..Default::default() }
}

/// The `__typename` type of a selection on `typeName`: a literal for concrete types (§9.2).
fn typename_type(type_name: &str, context: &TypeContext) -> String {
    match context.schema.possible_types.get(type_name) {
        Some(possible) if possible.len() == 1 && possible[0] == type_name => {
            json_string(type_name)
        }
        _ => "string".to_string(),
    }
}

/// The concrete types an inline fragment's condition covers.
fn concrete_conditions(condition: &str, context: &TypeContext) -> Vec<String> {
    match context.schema.possible_types.get(condition) {
        Some(possible) if !possible.is_empty() => possible.clone(),
        _ => vec![condition.to_string()],
    }
}

/// The §9.2 total discriminated union for an abstract selection.
#[allow(clippy::too_many_arguments)]
fn render_abstract_union(
    selection: &SubscriptionSelection,
    type_name: &str,
    mode: Mode,
    context: &TypeContext,
    depth: usize,
    root: bool,
    frame_object: bool,
    top_level: bool,
    addressable: bool,
) -> String {
    let branches = &selection.abstract_fields;
    let mut parts: Vec<String> = Vec::new();
    for (condition, branch) in branches.iter() {
        if condition == "%other" {
            continue;
        }
        let merged = merge_render_selection(branch, selection);
        for concrete in concrete_conditions(condition, context) {
            // each concrete branch decides its own addressability: an interface may mix keyed and
            // key-less implementations, and only the keyed ones can carry a fragment reference
            parts.push(render_type(
                &merged,
                &concrete,
                mode,
                context,
                depth,
                root,
                frame_object,
                top_level,
                Some(&concrete),
                addressable && !context.schema.is_embedded(&concrete),
            ));
        }
    }
    let other = match branches.get("%other") {
        Some(other) => other.clone(),
        None => SubscriptionSelection {
            fields: selection.fields.clone(),
            ..Default::default()
        },
    };
    parts.push(render_type(
        &other,
        type_name,
        mode,
        context,
        depth,
        root,
        frame_object,
        top_level,
        Some("%other"),
        addressable,
    ));
    parts.join(" | ")
}

/// `branch` plus any of `parent`'s fields the branch does not already have; no branches.
fn merge_render_selection(
    branch: &SubscriptionSelection,
    parent: &SubscriptionSelection,
) -> SubscriptionSelection {
    let mut fields = branch.fields.clone();
    for (name, field) in parent.fields.iter() {
        if name == "__typename" || fields.contains_key(name) {
            continue;
        }
        fields.insert(name, field.clone());
    }
    let mut fragments = branch.fragments.clone();
    for (name, spec) in parent.fragments.iter() {
        fragments.insert(name, spec.clone());
    }
    SubscriptionSelection { fields, fragments, abstract_fields: JsObject::new() }
}

/// Fragment references visible on a composite of `typeName` (§9.2, ` $fragments`).
fn collect_refs(
    selection: &SubscriptionSelection,
    type_name: &str,
    context: &TypeContext,
) -> Vec<String> {
    let mut found: Vec<String> = Vec::new();
    let mut visited: Vec<String> = Vec::new();
    fn walk(
        current: &SubscriptionSelection,
        nested: bool,
        type_name: &str,
        context: &TypeContext,
        found: &mut Vec<String>,
        visited: &mut Vec<String>,
    ) {
        for (spread, _) in current.fragments.iter() {
            let condition = fragment_type_of(context.document, spread);
            if !nested
                && condition
                    .map(|condition| intersects(condition, type_name, context))
                    .unwrap_or(false)
            {
                if !found.iter().any(|name| name == spread) {
                    found.push(spread.to_string());
                }
            }
            if visited.iter().any(|name| name == spread) {
                continue;
            }
            visited.push(spread.to_string());
            if let Some(inner) = fragment_selection_of(context.document, spread) {
                walk(inner, true, type_name, context, found, visited);
            }
        }
    }
    walk(selection, false, type_name, context, &mut found, &mut visited);
    found.sort_by(|a, b| compare_names(a, b));
    found
}

/// True when two type conditions can describe the same runtime object.
fn intersects(a: &str, b: &str, context: &TypeContext) -> bool {
    let left = context.schema.possible_types.get(a).cloned().unwrap_or_else(|| vec![a.to_string()]);
    let right = context.schema.possible_types.get(b).cloned().unwrap_or_else(|| vec![b.to_string()]);
    left.iter().any(|name| right.contains(name))
}

/// One rendered field line, or `None` when the mode prunes the field.
fn render_field(
    name: &str,
    field: &FieldSpec,
    mode: Mode,
    context: &TypeContext,
    depth: usize,
    root_field: bool,
    addressable: bool,
) -> Option<String> {
    let visible = field.visible == Some(true) || name == "__typename";
    if mode != Mode::Unmasked && !visible && field.selection.is_none() {
        return None;
    }
    if mode == Mode::Frame
        && field.loading.is_some()
        && (field.selection.is_none()
            || field.loading.as_ref().map(|loading| loading.kind == "value").unwrap_or(false))
    {
        // §7.1/§7.2: a `kind: 'value'` field is the `Pending` sentinel itself, whatever its
        // shape. That includes a list field under a cascade with no `@loading(count:)`: the
        // frame is a single `Pending`, not an array of frames (D3).
        return if visible || name == "__typename" {
            Some(format!("{}readonly {}: LoadingType;", tab(depth), quote_if_needed(name)))
        } else {
            None
        };
    }

    let optional = field
        .directives
        .as_ref()
        .map(|directives| {
            directives.iter().any(|directive| {
                matches!(directive.name.as_str(), "include" | "skip" | "when" | "when_not")
            })
        })
        .unwrap_or(false);
    // §7.13: a `@defer`/`@stream` field is absent from the initial payload and arrives in a patch, so
    // it is optional in every type that can read it — the codegen `Incremental<T>` rule, spelled as a
    // `?` at the use site. `has<Label>` proves it is there.
    let deferred = field.defer.as_ref().map(|defer| defer.kind == "fragment").unwrap_or(false);
    let body = render_field_type(field, mode, context, depth, root_field, addressable);
    // A masked selection keeps an invisible field only when it carries at least one
    // rendered descendant (the injected `pageInfo` around user-selected leaves).
    if mode != Mode::Unmasked && !visible && body == EMPTY_OBJECT {
        return None;
    }
    let comment = key_comment(name, field, context);
    let prefix = match comment {
        Some(comment) => format!("{}{}\n", tab(depth), comment),
        None => String::new(),
    };
    let question =
        if optional || deferred || mode == Mode::Optimistic { "?" } else { "" };
    Some(format!(
        "{prefix}{}readonly {}{question}: {body};",
        tab(depth),
        quote_if_needed(name)
    ))
}

/// The doc comment the injected key field carries in `$data` (§3.5, `SpriteInfo$data`).
fn key_comment(name: &str, _field: &FieldSpec, context: &TypeContext) -> Option<String> {
    if context.document.document.kind != ArtifactKind::Fragment {
        return None;
    }
    let type_name = injected_key_of(context.document, name)?;
    Some(format!(
        "/** Injected key field: present and visible because `{type_name}` has an `{name}` (§3.5, §6.1). */"
    ))
}

/// Applies the artifact's type-modifier string to produce the field's TS type.
fn render_field_type(
    field: &FieldSpec,
    mode: Mode,
    context: &TypeContext,
    depth: usize,
    root_field: bool,
    addressable: bool,
) -> String {
    let node = safe_parse_type(&field.modifiers);
    let base = |named: &str| -> String {
        if field.selection.is_some() && context.schema.possible_types.get(named).is_some() {
            let nested_mode =
                if mode == Mode::Data && field.loading.is_some() { Mode::Data } else { mode };
            // A composite that is itself under a loading state is a frame object: that includes the
            // elements of an `@loading(count: n)` list, which are frames at runtime but were typed as
            // loaded objects (K1d).
            let frame_object = mode == Mode::Frame
                && field.visible == Some(true)
                && field
                    .loading
                    .as_ref()
                    .map(|loading| loading.kind == "continue")
                    .unwrap_or(false);
            let child_addressable = addressable && !context.schema.is_embedded(named);
            let branches = field.abstract_fields.clone().unwrap_or_default();
            if field.abstract_ == Some(true) && !branches.is_empty() {
                let mut selection = field.selection.clone().expect("selection present");
                selection.abstract_fields = branches;
                return render_abstract_union(
                    &selection,
                    named,
                    nested_mode,
                    context,
                    depth,
                    root_field,
                    frame_object,
                    false,
                    addressable,
                );
            }
            return render_type(
                field.selection.as_ref().expect("selection present"),
                named,
                nested_mode,
                context,
                depth,
                root_field,
                frame_object,
                false,
                None,
                child_addressable,
            );
        }
        let leaf = leaf_ts_type(named, context);
        if mode == Mode::Data && field.loading.is_some() && field.selection.is_none() {
            return format!("LoadingType | {leaf}");
        }
        leaf
    };
    // The frame branch of a document's own root field is the frame itself and drops
    // nullability; every nested frame keeps `| null` because it can be absent.
    let keep_nullable =
        !(mode == Mode::Frame && root_field && context.document.kind != ArtifactKind::Fragment);
    apply_wrappers(
        &node,
        &base,
        if keep_nullable { Mode::Unmasked } else { Mode::Frame },
        outermost_nullability(field),
    )
}

/// The artifact's decision about the field's **outermost** nullability.
fn outermost_nullability(field: &FieldSpec) -> Outermost {
    if field.required == Some(true) {
        return Outermost::NonNull;
    }
    if field.nullable == Some(true) { Outermost::Nullable } else { Outermost::Schema }
}

/// Applies the type wrappers of `node` to `base`.
fn apply_wrappers(
    node: &TypeNode,
    base: &dyn Fn(&str) -> String,
    mode: Mode,
    outermost: Outermost,
) -> String {
    fn walk(
        current: &TypeNode,
        nullable: bool,
        depth: usize,
        base: &dyn Fn(&str) -> String,
        mode: Mode,
        outermost: Outermost,
    ) -> String {
        if let TypeNode::NonNull(inner) = current {
            return walk(&inner.type_node, false, depth, base, mode, outermost);
        }
        if let TypeNode::List(inner) = current {
            let inner_text = walk(&inner.type_node, true, depth + 1, base, mode, outermost);
            let list = format!("ReadonlyArray<{inner_text}>");
            let nullable_here = if depth == 0 && outermost != Outermost::Schema && mode != Mode::Frame
            {
                outermost == Outermost::Nullable
            } else {
                nullable
            };
            return if nullable_here && mode != Mode::Frame {
                format!("{list} | null")
            } else {
                list
            };
        }
        let named = &current.named_type().name.value;
        let text = base(named);
        // Nullability comes from the `TypeNode`, never from the rendered text: an
        // object type whose body contains `| null` for a nested field is still a
        // non-nullable object (A8/B2).
        let nullable_here = if depth == 0 && outermost != Outermost::Schema && mode != Mode::Frame {
            outermost == Outermost::Nullable
        } else {
            nullable
        };
        if nullable_here && mode != Mode::Frame { format!("{text} | null") } else { text }
    }
    walk(node, true, 0, base, mode, outermost)
}

/// A named type's TypeScript rendering (§9.1).
fn leaf_ts_type(name: &str, context: &TypeContext) -> String {
    if let Some(configured) = context.config.scalars.get(name) {
        return configured.type_name.clone().unwrap_or_default();
    }
    if let Some(built_in) = built_in_scalar(name) {
        return built_in.to_string();
    }
    if context.schema.enums.get(name).is_some() {
        return format!("{name}$options");
    }
    if context.schema.input_types.get(name).is_some() {
        return name.to_string();
    }
    "unknown".to_string()
}

/// The built-in scalar mapping (`BUILT_IN_SCALARS`).
fn built_in_scalar(name: &str) -> Option<&'static str> {
    match name {
        "String" | "ID" => Some("string"),
        "Int" | "Float" => Some("number"),
        "Boolean" => Some("boolean"),
        _ => None,
    }
}

/// The TS type of a GraphQL type string (`Int!`), used by `$input`.
fn ts_type_of_type_string(text: &str, context: Option<&TypeContext>) -> String {
    let node = safe_parse_type(text);
    let base = |named: &str| -> String {
        match context {
            Some(context) => leaf_ts_type(named, context),
            None => built_in_scalar(named).unwrap_or("unknown").to_string(),
        }
    };
    apply_wrappers(&node, &base, Mode::Unmasked, Outermost::Schema)
}

