/// The generated `tsconfig.json`, verbatim from §2.4.
pub fn emit_tsconfig() -> String {
    let strings = |items: &[&str]| Json::Arr(items.iter().map(|item| Json::Str((*item).into())).collect());
    let root = Json::Obj(vec![
        (
            "compilerOptions".into(),
            Json::Obj(vec![
                ("baseUrl".into(), Json::Str(".".into())),
                (
                    "paths".into(),
                    Json::Obj(vec![
                        ("$flamme".into(), strings(&["./index.ts"])),
                        ("$flamme/*".into(), strings(&["./*"])),
                    ]),
                ),
                ("rootDirs".into(), strings(&["..", "."])),
                ("target".into(), Json::Str("ES2023".into())),
                ("lib".into(), strings(&["ES2023"])),
                ("module".into(), Json::Str("ESNext".into())),
                ("moduleResolution".into(), Json::Str("bundler".into())),
                ("moduleDetection".into(), Json::Str("force".into())),
                ("resolveJsonModule".into(), Json::Bool(true)),
                ("types".into(), Json::Arr(Vec::new())),
                ("strict".into(), Json::Bool(true)),
                ("noUncheckedIndexedAccess".into(), Json::Bool(true)),
                ("exactOptionalPropertyTypes".into(), Json::Bool(true)),
                ("noImplicitOverride".into(), Json::Bool(true)),
                ("noImplicitReturns".into(), Json::Bool(true)),
                ("noFallthroughCasesInSwitch".into(), Json::Bool(true)),
                ("noUnusedLocals".into(), Json::Bool(true)),
                ("noUnusedParameters".into(), Json::Bool(true)),
                ("useUnknownInCatchVariables".into(), Json::Bool(true)),
                ("verbatimModuleSyntax".into(), Json::Bool(true)),
                ("isolatedModules".into(), Json::Bool(true)),
                ("noEmit".into(), Json::Bool(true)),
                ("skipLibCheck".into(), Json::Bool(true)),
                ("forceConsistentCasingInFileNames".into(), Json::Bool(true)),
            ]),
        ),
        (
            "include".into(),
            strings(&[
                "ambient.d.ts",
                "index.ts",
                "props.ts",
                "runtime/index.ts",
                "artifacts/**/*.ts",
                "graphql/**/*.ts",
                "../src/**/*.ts",
                "../src/**/*.vue",
                "../test/**/*.ts",
                "../vite.config.ts",
            ]),
        ),
    ]);
    format!("{}\n", json_pretty(&root))
}

/// The barrel users import documents from (§4.7).
pub fn emit_index(documents: &[IrDocument]) -> String {
    // A composed route document is not app API: it is a real operation on the wire and a real
    // artifact, but nothing imports it by name, so it stays out of the barrel
    // (`research/route-composition-design.md` §1.5).
    let mut sorted: Vec<&IrDocument> = documents
        .iter()
        .filter(|document| document.document.surface != crate::extract::DocumentSurface::Composed)
        .collect();
    sorted.sort_by(|a, b| compare_names(&a.name, &b.name));
    let mut lines: Vec<String> = vec![
        GENERATED_BANNER.to_string(),
        String::new(),
        "export * from './runtime/index'".into(),
        String::new(),
    ];
    let mut keys: Vec<String> = Vec::new();
    for document in &sorted {
        let name = &document.name;
        lines.push(format!("export {{ default as {name} }} from './artifacts/{name}'"));
        let types: Vec<String> = if document.kind == ArtifactKind::Fragment {
            vec![format!("{name}$data"), format!("{name}$key"), format!("{name}$artifact")]
        } else {
            vec![
                format!("{name}$result"),
                format!("{name}$input"),
                format!("{name}$unmasked"),
                format!("{name}$artifact"),
            ]
        };
        lines.push(format!("export type {{ {} }} from './artifacts/{name}'", types.join(", ")));
        keys.push(json_string(&document.document.raw));
    }
    lines.push(String::new());
    lines.push("/** Typed `graphql()`: a keyed lookup, not an overload table. */".into());
    lines.push("export interface DocumentMap {".into());
    let mut seen: Vec<&String> = Vec::new();
    for (index, key) in keys.iter().enumerate() {
        if seen.contains(&key) {
            continue;
        }
        seen.push(key);
        let name = sorted.get(index).map(|document| document.name.as_str()).unwrap_or("unknown");
        lines.push(format!("  {key}: typeof import('./artifacts/{name}').default"));
    }
    lines.push("}".into());
    lines.push(String::new());
    lines.push("/**".into());
    lines.push(" * The `graphql()` fallback: the template text is not a key in `DocumentMap`.".into());
    lines.push(" *".into());
    lines.push(" * This type exists to be *named* in the error. A stale template (the document".into());
    lines.push(" * was edited without running `flamme generate`) is the cause, so the fallback".into());
    lines.push(" * type says so; a `never` fallback instead type-checked silently at the call".into());
    lines.push(" * site and produced a misleading downstream error (\"Property … does not exist".into());
    lines.push(" * on type 'never'\").".into());
    lines.push(" */".into());
    lines.push("export interface FLM_DocumentNotInGeneratedMap {".into());
    lines.push(
        "  readonly ' $documentNotInGeneratedMap': 'run `flamme generate`: this document text is not in DocumentMap'"
            .into(),
    );
    lines.push("}".into());
    lines.push(String::new());
    lines.push("export function graphql<T extends keyof DocumentMap>(source: T): DocumentMap[T]".into());
    lines.push("export function graphql(source: string): FLM_DocumentNotInGeneratedMap".into());
    lines.push("export function graphql(source: string): never {".into());
    lines.push("  throw new Error(`graphql() must be compiled away: ${source.slice(0, 40)}`)".into());
    lines.push("}".into());
    format!("{}\n", lines.join("\n"))
}

/// `runtime/index.ts`: the runtime re-export plus the generated constants (§4.7).
pub fn emit_runtime_index(schema: &SchemaIndex, config: &RustConfig) -> String {
    let mut keys: Vec<&str> = schema.key_fields.keys();
    keys.sort_by(|a, b| compare_names(a, b));
    let mut lines = vec![
        GENERATED_BANNER.to_string(),
        String::new(),
        "export * from '@flamme/runtime'".into(),
        String::new(),
        format!("export const COMPILER_VERSION = '{COMPILER_VERSION}'"),
        format!("export const RUNTIME_VERSION = '{RUNTIME_VERSION}'"),
        String::new(),
        "/** Key fields per type, as resolved from the schema and the config. */".into(),
        "export const cacheKeys: Readonly<Record<string, readonly string[]>> = {".into(),
    ];
    for name in keys {
        let fields = schema.key_fields.get(name).cloned().unwrap_or_default();
        let rendered: Vec<String> =
            fields.iter().map(|field| json_string(field)).collect();
        lines.push(format!("  {}: [{}],", json_string(name), rendered.join(", ")));
    }
    lines.push("}".into());
    lines.push(String::new());
    let defaults: Vec<String> =
        config.default_keys.iter().map(|key| json_string(key)).collect();
    lines.push(format!(
        "export const defaultKeys: readonly string[] = [{}]",
        defaults.join(", ")
    ));
    format!("{}\n", lines.join("\n"))
}

/// The schema this artifact set was compiled against, with the compiler's directives (§7).
pub fn emit_schema_file(schema: &SchemaIndex) -> String {
    let base = if schema.sdl.ends_with('\n') {
        schema.sdl.clone()
    } else {
        format!("{}\n", schema.sdl)
    };
    if schema.has_key_directive {
        return base;
    }
    let missing: Vec<&str> = SCHEMA_DIRECTIVE_DEFINITIONS
        .iter()
        .copied()
        .filter(|definition| {
            let name = definition_name(definition);
            !has_definition(&base, &name)
        })
        .collect();
    if missing.is_empty() { base } else { format!("{base}\n{}\n", missing.join("\n")) }
}

/// The directive or enum name a compiler directive definition declares.
fn definition_name(definition: &str) -> String {
    for marker in ["directive", "enum"] {
        if let Some(at) = definition.find(marker) {
            let rest = &definition[at + marker.len()..];
            let rest = rest.trim_start();
            let rest = rest.strip_prefix('@').unwrap_or(rest);
            let end = rest
                .find(|character: char| !(character.is_ascii_alphanumeric() || character == '_'))
                .unwrap_or(rest.len());
            return rest[..end].to_string();
        }
    }
    String::new()
}

/// True for the characters JavaScript's `\s` matches, which is what the
/// `emitSchemaFile` regexes use (it differs from Rust's `char::is_whitespace`:
/// `\s` includes U+FEFF and excludes U+0085).
fn is_js_whitespace(character: char) -> bool {
    matches!(
        character,
        '\t' | '\n'
            | '\u{b}'
            | '\u{c}'
            | '\r'
            | ' '
            | '\u{a0}'
            | '\u{1680}'
            | '\u{2028}'
            | '\u{2029}'
            | '\u{202f}'
            | '\u{205f}'
            | '\u{3000}'
            | '\u{feff}'
    ) || ('\u{2000}'..='\u{200a}').contains(&character)
}

/// True when `sdl` declares the directive or enum `name` at a line start.
fn has_definition(sdl: &str, name: &str) -> bool {
    let mut index = 0;
    while index < sdl.len() {
        let rest = &sdl[index..];
        let next = match (rest.find("directive"), rest.find("enum")) {
            (Some(directive), Some(enumeration)) => Some(directive.min(enumeration)),
            (Some(found), None) | (None, Some(found)) => Some(found),
            (None, None) => None,
        };
        let Some(offset) = next else {
            return false;
        };
        let at = index + offset;
        index = at + 1;
        // `(^|\n)\s*`: some position between a line start and the keyword has to be
        // whitespace only, so the whitespace run before the keyword either reaches
        // the start of the text, follows a newline, or contains one.
        let before = &sdl[..at];
        let run_start = before.trim_end_matches(is_js_whitespace).len();
        let anchored = run_start == 0
            || before[..run_start].ends_with('\n')
            || before[run_start..].contains('\n');
        if !anchored {
            continue;
        }
        let keyword = if sdl[at..].starts_with("directive") { "directive" } else { "enum" };
        let after_keyword = &sdl[at + keyword.len()..];
        let trimmed = after_keyword.trim_start_matches(is_js_whitespace);
        if trimmed.len() == after_keyword.len() {
            continue;
        }
        let candidate = if keyword == "directive" {
            match trimmed.strip_prefix('@') {
                Some(candidate) => candidate,
                None => continue,
            }
        } else {
            trimmed
        };
        if !candidate.starts_with(name) {
            continue;
        }
        let end = at + keyword.len() + (after_keyword.len() - candidate.len()) + name.len();
        let bounded = end == sdl.len()
            || !(sdl[end..].chars().next().expect("char").is_ascii_alphanumeric()
                || sdl[end..].starts_with('_'));
        if bounded {
            return true;
        }
    }
    false
}

/// Enum unions, one per enum in the schema (§9.1).
pub fn emit_enums(schema: &SchemaIndex) -> String {
    let mut lines = vec![GENERATED_BANNER.to_string(), String::new()];
    let mut names: Vec<&str> = schema.enums.keys();
    names.sort_by(|a, b| compare_names(a, b));
    for name in names {
        let values = schema.enums.get(name).cloned().unwrap_or_default();
        lines.push(format!("export type {name}$options ="));
        for value in &values {
            lines.push(format!("  | {}", json_string(value)));
        }
        lines.push(String::new());
    }
    format!("{}\n", lines.join("\n").trim_end())
}

/// Input object interfaces for every input type (§9.1).
pub fn emit_inputs(schema: &SchemaIndex) -> String {
    let mut lines = vec![GENERATED_BANNER.to_string(), String::new()];
    let mut names: Vec<&str> = schema.input_types.keys();
    names.sort_by(|a, b| compare_names(a, b));
    for name in names {
        lines.push(format!("export interface {name} {{"));
        let fields = schema.input_types.get(name).cloned().unwrap_or_default();
        let mut field_names: Vec<&str> = fields.keys();
        field_names.sort_by(|a, b| compare_names(a, b));
        for field in field_names {
            let text = fields.get(field).cloned().unwrap_or_else(|| "String".into());
            let optional = !text.ends_with('!');
            lines.push(format!(
                "  readonly {field}{}: {};",
                if optional { "?" } else { "" },
                ts_input_type(&text, schema)
            ));
        }
        lines.push("}".into());
        lines.push(String::new());
    }
    format!("{}\n", lines.join("\n").trim_end())
}

/// The TS type of one input-object field's GraphQL type string.
fn ts_input_type(text: &str, schema: &SchemaIndex) -> String {
    let node = safe_parse_type(text);
    let base = |named: &str| -> String {
        // An input object is an interface in this very file, so a nested input
        // object types as its own name rather than `unknown` (A9).
        if schema.input_types.get(named).is_some() {
            return named.to_string();
        }
        if schema.enums.get(named).is_some() {
            return format!("{named}$options");
        }
        built_in_scalar(named).unwrap_or("unknown").to_string()
    };
    apply_wrappers(&node, &base, Mode::Unmasked, Outermost::Schema)
}

/// Module declarations for document imports, one per basename per configured extension.
///
/// `declare module '*/<Name>.gql'` and `declare module '*/<Name>.graphql'` both resolve, so an
/// `import Doc from './Doc.graphql'` is typed exactly like its `.gql` spelling. The extension list
/// is `routing.documentExtensions`, which extraction and the import rewrite read too; the spelling
/// is byte-identical to `emitAmbient` in `packages/core/src/emit.ts`.
pub fn emit_ambient(documents: &[IrDocument], extensions: &[String]) -> String {
    let mut lines = vec![GENERATED_BANNER.to_string(), String::new()];
    let mut sorted: Vec<&IrDocument> = documents
        .iter()
        .filter(|document| document.document.surface != crate::extract::DocumentSurface::Composed)
        .collect();
    sorted.sort_by(|a, b| compare_names(&a.name, &b.name));
    let mut seen: Vec<&str> = Vec::new();
    for document in sorted {
        if document.kind == ArtifactKind::Fragment || seen.contains(&document.name.as_str()) {
            continue;
        }
        seen.push(&document.name);
        let name = &document.name;
        for extension in extensions {
            lines.push(format!("declare module '*/{name}{extension}' {{"));
            lines.push(format!(
                "\tconst document: typeof import('./artifacts/{name}')['default']"
            ));
            lines.push("\texport default document".into());
            lines.push("}".into());
            lines.push(String::new());
        }
    }
    format!("{}\n", lines.join("\n").trim_end())
}

/// One `@list` registration: the element type and whether the field is a connection.
type ListRegistration = (String, bool);

/// Every `@list` field of every document, in the order the map saw them.
fn schema_lists(documents: &[IrDocument]) -> Vec<(String, ListRegistration)> {
    let mut map: Vec<(String, ListRegistration)> = Vec::new();
    for document in documents {
        let mut entries: Vec<(String, ListRegistration)> = Vec::new();
        collect_lists(&document.selection, &mut entries);
        for (name, value) in entries {
            match map.iter_mut().find(|(key, _)| *key == name) {
                Some(slot) => slot.1 = value,
                None => map.push((name, value)),
            }
        }
    }
    map
}

/// Every `@list` field of a selection, fields first then their nested selections.
fn collect_lists(selection: &SubscriptionSelection, out: &mut Vec<(String, ListRegistration)>) {
    for (_, field) in selection.fields.iter() {
        if let Some(list) = &field.list {
            out.push((list.name.clone(), (list.type_name.clone(), list.connection)));
        }
        if let Some(selection) = &field.selection {
            collect_lists(selection, out);
        }
    }
}

/// The machine-readable index for the runtime, HMR and the CLI (§4.7).
pub fn emit_manifest(
    documents: &[IrDocument],
    schema: &SchemaIndex,
    config: &RustConfig,
    persisted: bool,
) -> String {
    let mut sorted: Vec<&IrDocument> = documents.iter().collect();
    sorted.sort_by(|a, b| compare_names(&a.name, &b.name));

    let mut lists = schema_lists(documents);
    lists.sort_by(|a, b| compare_names(&a.0, &b.0));
    let mut lists_record: JsObject<ListRegistration> = JsObject::new();
    for (name, value) in lists {
        lists_record.insert(name, value);
    }
    let mut fragments: JsObject<String> = JsObject::new();
    for document in &sorted {
        if document.kind != ArtifactKind::Fragment {
            continue;
        }
        fragments.insert(document.name.clone(), document.root_type.clone());
    }
    let mut paginated: JsObject<Vec<String>> = JsObject::new();
    for document in &sorted {
        if document.paginated.is_empty() {
            continue;
        }
        paginated.insert(
            document.name.clone(),
            document
                .paginated
                .iter()
                .map(|path| path.last().cloned().unwrap_or_default())
                .collect(),
        );
    }

    let mut entries: Vec<(String, Json)> = vec![
        ("version".into(), Json::Int(1)),
        ("compiler".into(), Json::Str(COMPILER_VERSION.into())),
        ("runtime".into(), Json::Str(RUNTIME_VERSION.into())),
        ("schemaHash".into(), Json::Str(schema.hash.clone())),
        (
            "documents".into(),
            Json::Arr(
                sorted
                    .iter()
                    .map(|document| {
                        Json::Obj(vec![
                            ("name".into(), Json::Str(document.name.clone())),
                            ("kind".into(), Json::Str(document.kind.as_str().into())),
                            ("hash".into(), Json::Str(document.hash.clone())),
                            (
                                "file".into(),
                                Json::Str(format!("artifacts/{}.ts", document.name)),
                            ),
                            (
                                "sources".into(),
                                Json::Arr(vec![Json::Str(document.source.clone())]),
                            ),
                        ])
                    })
                    .collect(),
            ),
        ),
        (
            "lists".into(),
            Json::Obj(
                lists_record
                    .keys()
                    .into_iter()
                    .map(|name| {
                        let (type_name, connection) =
                            lists_record.get(name).cloned().unwrap_or_default();
                        (
                            name.to_string(),
                            Json::Obj(vec![
                                ("type".into(), Json::Str(type_name)),
                                ("connection".into(), Json::Bool(connection)),
                            ]),
                        )
                    })
                    .collect(),
            ),
        ),
        (
            "fragments".into(),
            Json::Obj(
                fragments
                    .keys()
                    .into_iter()
                    .map(|name| {
                        (
                            name.to_string(),
                            Json::Str(fragments.get(name).cloned().unwrap_or_default()),
                        )
                    })
                    .collect(),
            ),
        ),
        (
            "paginated".into(),
            Json::Obj(
                paginated
                    .keys()
                    .into_iter()
                    .map(|name| {
                        let paths = paginated.get(name).cloned().unwrap_or_default();
                        (
                            name.to_string(),
                            Json::Arr(paths.into_iter().map(Json::Str).collect()),
                        )
                    })
                    .collect(),
            ),
        ),
    ];
    if persisted {
        let mut operations: JsObject<String> = JsObject::new();
        for (name, id) in persisted_id_map(documents) {
            operations.insert(name, id);
        }
        entries.push((
            "persisted".into(),
            Json::Obj(vec![
                ("file".into(), Json::Str(PERSISTED_MANIFEST_FILE.into())),
                ("idRule".into(), Json::Str(PERSISTED_ID_RULE.into())),
                (
                    "operations".into(),
                    Json::Obj(
                        operations
                            .keys()
                            .into_iter()
                            .map(|name| {
                                (
                                    name.to_string(),
                                    Json::Str(operations.get(name).cloned().unwrap_or_default()),
                                )
                            })
                            .collect(),
                    ),
                ),
            ]),
        ));
    }
    entries.push((
        "defaultKeys".into(),
        Json::Arr(config.default_keys.iter().map(|key| Json::Str(key.clone())).collect()),
    ));
    format!("{}\n", json_pretty(&Json::Obj(entries)))
}

/// `props.ts`.
pub fn emit_props_file(documents: &[IrDocument]) -> String {
    emit_props_module(documents, &EmitPropsOptions::default())
}

/// Adds the generated banner to `text` unless it already starts with it.
pub fn with_generated_banner(text: &str) -> String {
    if text.starts_with(GENERATED_BANNER) {
        return text.to_string();
    }
    let mut lines: Vec<&str> = text.split('\n').collect();
    if let Some(first) = lines.first() {
        if first.starts_with("// GENERATED by ") && first.ends_with("do not edit.") {
            lines.remove(0);
            // a bare `//` continuation line belongs to the header it followed
            if lines.first() == Some(&"//") {
                lines.remove(0);
            }
        }
    }
    format!("{GENERATED_BANNER}\n{}", lines.join("\n"))
}

/// The whole generated tree as `(path relative to runtimeDir, contents)` pairs,
/// in the order the plugins contribute them (the writer sorts before writing).
pub fn emit_tree(
    documents: &[IrDocument],
    schema: &SchemaIndex,
    config: &RustConfig,
    persisted: bool,
) -> Vec<(String, String)> {
    emit_tree_filtered(documents, schema, config, persisted, |_| true)
}

/// [`emit_tree`], with the artifact modules of the documents `keep_artifact`
/// rejects left out.
///
/// The aggregate members are always emitted and always describe the whole
/// project: an incremental run re-serializes the documents it rebuilt, while
/// `index.ts` and `manifest.json` still carry every document. The caller keeps
/// the artifacts it skips on disk (`session.rs`), so the tree a run returns stays
/// the tree the writer must land.
pub fn emit_tree_filtered<F: Fn(&IrDocument) -> bool>(
    documents: &[IrDocument],
    schema: &SchemaIndex,
    config: &RustConfig,
    persisted: bool,
    keep_artifact: F,
) -> Vec<(String, String)> {
    let mut files: Vec<(String, String)> = Vec::new();
    for document in documents {
        if !keep_artifact(document) {
            continue;
        }
        files.push((
            format!("artifacts/{}.ts", document.name),
            emit_artifact(document, schema, config),
        ));
    }
    files.push(("index.ts".into(), emit_index(documents)));
    files.push((
        "ambient.d.ts".into(),
        emit_ambient(documents, &config.routing.document_extensions()),
    ));
    files.push(("props.ts".into(), emit_props_file(documents)));
    files.push(("schema.graphql".into(), emit_schema_file(schema)));
    files.push(("graphql/enums.ts".into(), emit_enums(schema)));
    files.push(("graphql/inputs.ts".into(), emit_inputs(schema)));
    files.push(("tsconfig.json".into(), emit_tsconfig()));
    files.push(("runtime/index.ts".into(), emit_runtime_index(schema, config)));
    files.push(("manifest.json".into(), emit_manifest(documents, schema, config, persisted)));
    if persisted {
        files.push((
            PERSISTED_MANIFEST_FILE.into(),
            emit_persisted_manifest(documents, COMPILER_VERSION),
        ));
    }
    files
}
